class EnergyShield {
  #maxStrength;
  #currentStrength;
  #isActive;

  constructor(maxStrength) {
    this.#maxStrength = maxStrength;
    this.#currentStrength = 0;
    this.#isActive = false;
  }

  activate() {
    if (this.#isActive) return; // Early return if already active
    this.#isActive = true;
    this.#currentStrength = this.#maxStrength;
  }

  deactivate() {
    if (!this.#isActive) return; // Early return if already inactive
    this.#isActive = false;
    this.#currentStrength = 0;
  }

  takeDamage(amount) {
    if (!this.#isActive) {
      return; // Early return: shield is inactive
    }
    if (amount <= 0) {
      return; // Early return: invalid damage amount
    }

    this.#currentStrength -= amount;
    if (this.#currentStrength <= 0) {
      this.#currentStrength = 0; // Prevent negative strength
      this.deactivate();
    }
  }

  get currentStrength() {
    return this.#currentStrength;
  }

  get isActive() {
    return this.#isActive;
  }
}

class Starship {
  constructor(name, shieldMaxStrength) {
    this.name = name;
    this.shield = new EnergyShield(shieldMaxStrength);
  }

  fireLasers() {
    return `${this.name} fires lasers!`;
  }
}

